import subprocess
branches=['rachel','monica','phoebe','joey','chandler','ross']
total=0
for b in branches:
    out=subprocess.check_output(['git','log','--format=%B%x1f', f'origin/friend/{b}'], text=True)
    for c in out.split('\x1f'):
        if 'Friend-Message: 1' in c:
            ep=None
            for line in c.splitlines():
                if line.startswith('Episode:'):
                    ep=line.split(':',1)[1].strip()
            if ep=='S05/E25':
                total+=1
print('count',total)
